/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic       clk,
    input  logic       reset,
    input  logic [2:0] s,
    output logic       fr2,
    output logic       fr1,
    output logic       fr0,
    output logic       dfr
);
    logic [1:0] level_r, level_n;
    logic supplemental_r;

    // Only physically ordered sensor patterns represent water levels.
    always_comb begin
        level_n = level_r;
        case (s)
            3'b000: level_n = 2'd0;
            3'b001: level_n = 2'd1;
            3'b011: level_n = 2'd2;
            3'b111: level_n = 2'd3;
            default: level_n = level_r;
        endcase
    end

    always_ff @(posedge clk) begin
        if (reset) begin
            level_r <= 2'd0;
            supplemental_r <= 1'b1;
        end else begin
            level_r <= level_n;
            if (level_n == 2'd0)
                supplemental_r <= 1'b1;
            else if (level_n == 2'd3)
                supplemental_r <= 1'b0;
            else if (level_n "'!= level_r)
                supplemental_r <= (level_n > level_r);
        end
    end

    always_comb begin
        fr2 = 1'"'b0;
        fr1 = 1'b0;
        fr0 = 1'b0;
        dfr = supplemental_r;
        case (level_r)
            2'd0: begin fr2 = 1'b1; fr1 = 1'b1; fr0 = 1'b1; end
            2'd1: begin fr1 = 1'b1; fr0 = 1'b1; end
            2'd2: begin fr0 = 1'b1; end
            2'd3: begin end
            default: begin end
        endcase
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv"

